import re
from collections.abc import Mapping
from dataclasses import dataclass

from selectolax.lexbor import LexborHTMLParser

from app.services.website_intel.models import PageVerdict

SCAN_CHARS = 200_000
LOW_TEXT_CHARS = 2_000
JS_SHELL_TEXT_CHARS = 400
CONSENT_WALL_TEXT_CHARS = 300
LOGIN_WALL_TEXT_CHARS = 200
SHELL_SCRIPT_SHARE = 0.8
SHELL_MAX_ROOT_CHILDREN = 3

WAF_SIGNATURES = (
    "microsoft-azure-application-gateway",
    "azure waf",
    "appgwazwaf",
    "reference #",
    "reference&#32;&#35;",
    "aws waf",
    "request blocked",
    "generated by cloudfront",
    "incapsula",
    "_incapsula_resource",
    "sucuri website firewall",
    "attention required! | cloudflare",
    "you have been blocked",
)
WAF_HEADERS = ("x-iinfo", "x-sucuri-id", "x-amzn-waf-action", "x-azure-ref-waf")
WAF_SERVERS = (
    "akamaighost",
    "akamai",
    "sucuri",
    "incapsula",
    "awselb",
    "microsoft-azure-application-gateway",
)
# challenge pages that a 200 status cannot hide; only trusted when the page carries little text
CHALLENGE_SIGNATURES = (
    "azure waf",
    "appgwazwaf",
    "checking you're not a robot",
    "checking you are not a robot",
    "_incapsula_resource",
    "sucuri website firewall",
)
CF_CHALLENGE_MARKERS = ("just a moment...", "cf-chl-", "challenge-form", "cf_chl_opt")
CAPTCHA_MARKERS = (
    "g-recaptcha",
    "h-captcha",
    "hcaptcha.com/1/api.js",
    "captcha-delivery.com",
    "geo.captcha-delivery",
)
GEO_BLOCK_TEXT = re.compile(
    r"not available in your (?:region|country|location)|unavailable in your (?:region|country)"
)
SOFT_404_TEXT = re.compile(
    r"page (?:not found|cannot be found|could not be found|doesn['’]t exist|does not exist)|404 (?:not found|error)"
)
CONSENT_ROOTS = (
    "onetrust-banner-sdk",
    "cybotcookiebotdialog",
    "didomi-host",
    "qc-cmp2-container",
    "truste-consent-track",
    "osano-cm-window",
)
COOKIE_BANNER = re.compile(r"class=[\"'][^\"']*cookie[^\"']*banner", re.IGNORECASE)
NOSCRIPT_JS = re.compile(r"<noscript[^>]*>[^<]*(?:enable|turn on)\s+javascript", re.IGNORECASE)
SCRIPT_BLOCK = re.compile(r"<script\b[^>]*>.*?</script>", re.IGNORECASE | re.DOTALL)
TITLE = re.compile(r"<title[^>]*>(.*?)</title>", re.IGNORECASE | re.DOTALL)
PASSWORD_INPUT = re.compile(r"type=[\"']?password")
APP_ROOT_IDS = ("root", "app", "__next", "__nuxt")


@dataclass(frozen=True)
class _Page:
    raw: str
    lowered: str
    title: str
    text_chars: int
    is_html: bool


def _text_chars(html: str) -> int:
    tree = LexborHTMLParser(html)
    for node in tree.css("script, style, noscript, template"):
        node.decompose()
    root = tree.body or tree.root
    return len(" ".join((root.text(separator=" ") if root is not None else "").split()))


class BlockClassifier:
    """maps one response to a PageVerdict; never tries to get past a block (plan 03 §5.6)."""

    def classify(
        self,
        *,
        status_code: int | None,
        headers: Mapping[str, str],
        body: str | None,
        content_type: str | None = None,
        extracted_text_chars: int | None = None,
        network_error: bool = False,
    ) -> PageVerdict:
        if network_error or status_code is None:
            return PageVerdict.error
        if status_code == 304:
            return PageVerdict.not_modified
        lowered_headers = {key.lower(): value.lower() for key, value in headers.items()}
        if lowered_headers.get("cf-mitigated") == "challenge":
            return PageVerdict.cf_challenge
        page = self._page(body or "", content_type, extracted_text_chars)
        challenge = self._challenge(page, status_code)
        if challenge is not None:
            return challenge
        if status_code >= 400:
            return self._error_status(status_code, page, lowered_headers)
        if 300 <= status_code < 400:
            return PageVerdict.error
        return self._success(page)

    @staticmethod
    def _page(body: str, content_type: str | None, extracted_text_chars: int | None) -> _Page:
        raw = body[:SCAN_CHARS]
        lowered = raw.lower()
        is_html = "html" in (content_type or "").lower() or "<html" in lowered[:2_000] or "<body" in lowered
        title_match = TITLE.search(raw) if is_html else None
        title = " ".join(title_match.group(1).split()).lower() if title_match else ""
        if extracted_text_chars is not None:
            text_chars = extracted_text_chars
        elif is_html:
            text_chars = _text_chars(raw)
        else:
            text_chars = len(" ".join(raw.split()))
        return _Page(raw=raw, lowered=lowered, title=title, text_chars=text_chars, is_html=is_html)

    @staticmethod
    def _challenge(page: _Page, status_code: int) -> PageVerdict | None:
        lowered = page.lowered
        if "/cdn-cgi/challenge-platform/" in lowered and (
            status_code in {403, 429, 503} or any(marker in lowered for marker in CF_CHALLENGE_MARKERS)
        ):
            return PageVerdict.cf_challenge
        if page.text_chars < LOW_TEXT_CHARS or status_code >= 400:
            if any(signature in lowered for signature in CHALLENGE_SIGNATURES):
                return PageVerdict.waf_block
            if any(marker in lowered for marker in CAPTCHA_MARKERS):
                return PageVerdict.captcha
        return None

    @staticmethod
    def _error_status(status_code: int, page: _Page, headers: Mapping[str, str]) -> PageVerdict:
        if status_code == 429:
            return PageVerdict.rate_limited
        if status_code == 451 or GEO_BLOCK_TEXT.search(page.lowered):
            return PageVerdict.geo_block
        if status_code in {401, 403, 406}:
            server = headers.get("server", "")
            signed = (
                any(signature in page.lowered for signature in WAF_SIGNATURES)
                or any(name in headers for name in WAF_HEADERS)
                or any(name in server for name in WAF_SERVERS)
            )
            if signed:
                return PageVerdict.waf_block
            return PageVerdict.login_wall if status_code == 401 else PageVerdict.error
        if status_code == 404:
            return PageVerdict.not_found
        if status_code == 410:
            return PageVerdict.gone
        if status_code >= 500:
            return PageVerdict.server_error
        return PageVerdict.error

    @staticmethod
    def _success(page: _Page) -> PageVerdict:
        if not page.is_html:
            return PageVerdict.ok
        lowered = page.lowered
        if GEO_BLOCK_TEXT.search(lowered) and page.text_chars < LOW_TEXT_CHARS:
            return PageVerdict.geo_block
        if SOFT_404_TEXT.search(page.title):
            return PageVerdict.soft_404
        if page.text_chars < LOGIN_WALL_TEXT_CHARS and PASSWORD_INPUT.search(lowered):
            return PageVerdict.login_wall
        if page.text_chars < CONSENT_WALL_TEXT_CHARS and (
            any(root in lowered for root in CONSENT_ROOTS) or COOKIE_BANNER.search(page.raw)
        ):
            return PageVerdict.consent_wall
        if page.text_chars < JS_SHELL_TEXT_CHARS and _looks_like_shell(page.raw):
            return PageVerdict.js_shell
        return PageVerdict.ok


def _looks_like_shell(html: str) -> bool:
    if NOSCRIPT_JS.search(html):
        return True
    script_bytes = sum(len(match.group(0)) for match in SCRIPT_BLOCK.finditer(html))
    if html and script_bytes / len(html) > SHELL_SCRIPT_SHARE:
        return True
    tree = LexborHTMLParser(html)
    for root_id in APP_ROOT_IDS:
        node = tree.css_first(f"div#{root_id}")
        if node is not None:
            children = [child for child in node.iter() if child.tag != "-text"]
            if len(children) <= SHELL_MAX_ROOT_CHILDREN:
                return True
    return False
